@Override
    public void loadAdditional(CompoundTag tag, HolderLookup.Provider provider) {
        super.loadAdditional(tag, provider);

        if (tag.contains(NBT_LOOT_TABLE, Tag.TAG_STRING)) {
            try {
                lootTable = ResourceKey.create(Registries.LOOT_TABLE, ResourceLocation.parse(tag.getString(NBT_LOOT_TABLE)));
                lootTableSeed = tag.getLong(NBT_LOOT_TABLE_SEED);
                setChanged();
            } catch (ResourceLocationException e) {
                lootTable = null;
                lootTableSeed = 0L;
            }
        } else {
            inventory.deserializeNBT(provider, tag.getCompound(NBT_ITEMS));
        }
    }

@Override
    public void loadAdditional(CompoundTag tag, HolderLookup.Provider provider) {
        super.loadAdditional(tag, provider);

        itemHandler.deserializeNBT(provider, tag.getCompound("Items"));
        setSensorSetting(tag.getString("sensorSetting"));
        dishSpeed = tag.getFloat("dishSpeed");
        sensorGuiText = tag.getString("sensorText");
        if (tag.contains("playerId", Tag.TAG_STRING)) {
            playerId = UUID.fromString(tag.getString("playerId"));
        }
        setupGPSPositions();
    }

@Override
    public void loadAdditional(CompoundTag tag, HolderLookup.Provider provider) {
        super.loadAdditional(tag, provider);

        rebootTimer = tag.getInt("startupTimer");
        inventory.deserializeNBT(provider, tag.getCompound("Items"));
        checkForNetworkValidity();
    }
